// 1. A Higher-Order Function that TAKES a function (Callback)
function greetUser(name, formatCallback) {
  const formattedName = formatCallback(name);
  console.log(`Welcome, ${formattedName}!`);
}

const makeUppercase = (str) => str.toUpperCase();
greetUser('alice', makeUppercase); // "Welcome, ALICE!"


// 2. A Higher-Order Function that RETURNS a function
function multiplyBy(factor) {
  return function(number) {
    return number * factor;
  }
}

const double = multiplyBy(2);
const triple = multiplyBy(3);

console.log(double(5)); // 10
console.log(triple(5)); // 15
